∀ {u : Real}
  {motive : (a : Real) → (a_1 : List.{0} (Prod.{0, 0} Real Real)) → (a_2 : Real) → Cholesky.DotTail u a a_1 a_2 → Prop}
  {motive_1 :
    {a : Real} →
      {a_1 : List.{0} (Prod.{0, 0} Real Real)} →
        {a_2 : Real} → (t : Cholesky.DotTail u a a_1 a_2) → Cholesky.DotTail.below t → Prop}
  {a : Real} {a_1 : List.{0} (Prod.{0, 0} Real Real)} {a_2 : Real} {t : Cholesky.DotTail u a a_1 a_2}
  (t_1 : Cholesky.DotTail.below t),
  (∀ (acc : Real), motive_1 ⋯ ⋯) →
    (∀ {acc p next out a b : Real} {xs : List.{0} (Prod.{0, 0} Real Real)}
        (multiply : Cholesky.Rounded u (HMul.hMul.{0, 0, 0} a b) p)
        (add : Cholesky.Rounded u (HAdd.hAdd.{0, 0, 0} acc p) next) (rest : Cholesky.DotTail u next xs out)
        (ih : Cholesky.DotTail.below rest) (rest_ih : motive next xs out rest), motive_1 ⋯ ⋯) →
      motive_1 t t_1

