∀ {n : Nat} {A R : Matrix.{0, 0, 0} (Fin n) (Fin n) Real} {u : Real},
  LE.le.{0} 0 u →
    LT.lt.{0} (HMul.hMul.{0, 0, 0} (↑(HAdd.hAdd.{0, 0, 0} n 1)) u) 1 →
      ∀ (i j : Fin n),
        Cholesky.EntryComputation u A R i j (R i j) →
          LE.le.{0}
            (abs.{0}
              (HSub.hSub.{0, 0, 0}
                (HAdd.hAdd.{0, 0, 0}
                  (List.sum.{0} (List.map.{0, 0} (fun ab => HMul.hMul.{0, 0, 0} ab.1 ab.2) (Cholesky.dotInputs R i j)))
                  (HMul.hMul.{0, 0, 0} (R i i) (R i j)))
                (A i j)))
            (HMul.hMul.{0, 0, 0} (CholeskyProof.g (HAdd.hAdd.{0, 0, 0} n 1) u)
              (HAdd.hAdd.{0, 0, 0}
                (List.sum.{0}
                  (List.map.{0, 0} (fun ab => abs.{0} (HMul.hMul.{0, 0, 0} ab.1 ab.2)) (Cholesky.dotInputs R i j)))
                (abs.{0} (HMul.hMul.{0, 0, 0} (R i i) (R i j)))))
